package com.projecteden.statistics.controller;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import com.projecteden.statistics.dto.StatisticsResponse;import com.projecteden.statistics.service.StatisticsService;import com.projecteden.user.domain.User;@RestController@RequestMapping("/api/statistics")public class StatisticsController{private final StatisticsService service;public StatisticsController(StatisticsService service){this.service=service;}@GetMapping("/me")public StatisticsResponse get(@AuthenticationPrincipal User user){return service.getMyStatistics(user.getId());}}
